import heapq


def widestPath(n, links, src, dst):
    adj = [[] for _ in range(n)]
    for a, b, c in links:
        adj[a].append((b, c))
        adj[b].append((a, c))
    best = [0] * n
    best[src] = float('inf')
    heap = [(-best[src], src)]
    while heap:
        negw, u = heapq.heappop(heap)
        w = -negw
        if w < best[u]:
            continue
        if u == dst:
            return w
        for v, c in adj[u]:
            cand = min(w, c)
            if cand > best[v]:
                best[v] = cand
                heapq.heappush(heap, (-cand, v))
    return -1
